import time
import board
import busio
import adafruit_max30102
import datetime

# Configuration
LOG_FILE = "heart_rate_log.txt"
SLEEP_INTERVAL = 1  # seconds

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_sensor(i2c_bus):
    """Initialize the MAX30102 sensor."""
    try:
        return adafruit_max30102.MAX30102(i2c_bus)
    except Exception as e:
        print(f"Error initializing MAX30102 sensor: {e}")
        return None

def read_sensor_data(sensor):
    """Read IR and RED ADC values from the sensor."""
    try:
        return sensor.ir_buffer, sensor.red_buffer
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None

def process_data(ir_buffer, red_buffer):
    """Process the IR and RED data to estimate heart rate."""
    if ir_buffer is None or red_buffer is None:
        return None

    peaks = []
    for i in range(len(ir_buffer) - 1):
        if ir_buffer[i] < red_buffer[i]:
            peaks.append(i)

    if len(peaks) < 3:
        return None  # Not enough peaks to estimate heart rate

    peak_to_peak = [peaks[i+1] - peaks[i] for i in range(len(peaks) - 1)]
    average_heart_rate = 60000.0 / (sum(peak_to_peak) / len(peak_to_peak)) if peak_to_peak else None
    return average_heart_rate

def log_heart_rate(heart_rate, log_file):
    """Log the heart rate to a file with a timestamp."""
    timestamp = datetime.datetime.now().isoformat()
    try:
        with open(log_file, "a") as f:
            f.write(f"{timestamp}, {heart_rate:.2f}\n")
    except Exception as e:
        print(f"Error writing to log file: {e}")

def main():
    """Main function to read and log heart rate data."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    sensor = initialize_sensor(i2c_bus)
    if sensor is None:
        return

    ir_buffer = []
    red_buffer = []

    try:
        while True:
            ir, red = read_sensor_data(sensor)
            if ir is not None and red is not None:
                ir_buffer.append(ir)
                red_buffer.append(red)

                if len(ir_buffer) > 200:
                    ir_buffer.pop(0)
                    red_buffer.pop(0)

                heart_rate = process_data(ir_buffer, red_buffer)
                if heart_rate is not None:
                    print(f"Heart Rate: {heart_rate:.2f} BPM")
                    log_heart_rate(heart_rate, LOG_FILE)

            time.sleep(SLEEP_INTERVAL)

    except KeyboardInterrupt:
        print("Exiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # No specific cleanup needed for I2C or the sensor object itself in this case,
        # but including a placeholder for potential future expansion.
        print("Program finished.")

if __name__ == "__main__":
    main()

