import time
import cv2
from pyzbar.pyzbar import decode

# Constants for camera and QR code settings
CAMERA_WIDTH = 64  # Reduced width for faster processing
CAMERA_HEIGHT = 64 # Reduced height for faster processing
DEFAULT_MESSAGE = "Hello, World!"


def initialize_camera():
    """Initializes the camera and returns the capture object."""
    try:
        cap = cv2.VideoCapture(0)
        if not cap.isOpened():
            raise IOError("Cannot open camera")
        cap.set(cv2.CAP_PROP_FRAME_WIDTH, CAMERA_WIDTH)
        cap.set(cv2.CAP_PROP_FRAME_HEIGHT, CAMERA_HEIGHT)
        return cap
    except Exception as e:
        print(f"Camera initialization error: {e}")
        return None


def capture_frame(cap):
    """Captures a single frame from the camera."""
    ret, frame = cap.read()
    if not ret:
        print("Failed to capture frame")
        return None
    return frame


def decode_qr_code(frame):
    """Decodes QR codes in a frame and returns the decoded message."""
    try:
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        decoded_objects = decode(gray)
        if decoded_objects:
            return decoded_objects[0].data.decode('utf-8')
        else:
            return None
    except Exception as e:
        print(f"QR code decoding error: {e}")
        return None


def process_qr_code(cap):
    """Main function to capture and process QR code."""
    frame = capture_frame(cap)
    if frame is None:
        return DEFAULT_MESSAGE

    message = decode_qr_code(frame)
    if message:
        print("QR code detected!")
        print(f"Message: {message}")
        return message
    else:
        print("No QR code detected.")
        return DEFAULT_MESSAGE


def release_resources(cap):
    """Releases camera resources."""
    if cap:
        cap.release()


def main():
    """Main function to run the QR code scanner."""
    cap = initialize_camera()
    if cap is None:
        print("Exiting due to camera initialization failure.")
        return

    try:
        message = process_qr_code(cap)
        print(f"Final Message: {message}")
    finally:
        release_resources(cap)


if __name__ == "__main__":
    main()

