import RPi.GPIO as GPIO
import time
import datetime
import logging
import logging.handlers
import os
import random
import argparse
import sys

# Constants and Configuration
DEFAULT_CONFIG_FILE = "hydroponics_config.txt"
DEFAULT_LOG_FILE = "hydroponics_system.log"
DEFAULT_LOG_LEVEL = "INFO"
DEFAULT_BLINK_DURATION = 0.5  # seconds
DEFAULT_BLINK_COUNT = 3
DEFAULT_SIMULATE_SENSORS = True
DEFAULT_DS18B20_PIN = 4 # Example pin, adjust as needed

# Custom Exception Classes
class SensorReadError(Exception):
    pass

class ConfigurationError(Exception):
    pass

# Configuration Management Functions
def parse_arguments():
    parser = argparse.ArgumentParser(description="Hydroponics Monitoring System")
    parser.add_argument("--config", default=DEFAULT_CONFIG_FILE, help="Path to the configuration file")
    return parser.parse_args()

def load_configuration(config_file):
    try:
        with open(config_file, "r") as f:
            temperature_threshold = float(f.readline().strip())
            ph_threshold = float(f.readline().strip())
            ec_threshold = float(f.readline().strip())
            temperature_offset = float(f.readline().strip())
            temperature_gain = float(f.readline().strip())
            ph_offset = float(f.readline().strip())
            ph_gain = float(f.readline().strip())
            ec_offset = float(f.readline().strip())
            ec_gain = float(f.readline().strip())
            return {
                "temperature_threshold": temperature_threshold,
                "ph_threshold": ph_threshold,
                "ec_threshold": ec_threshold,
                "temperature_offset": temperature_offset,
                "temperature_gain": temperature_gain,
                "ph_offset": ph_offset,
                "ph_gain": ph_gain,
                "ec_offset": ec_offset,
                "ec_gain": ec_gain,
            }
    except (IOError, ValueError) as e:
        raise ConfigurationError(f"Error parsing configuration file: {e}")

# Modular Subsystem Functions
def read_temperature():
    if args.simulate_sensors:
        return simulate_temperature()
    else:
        try:
            # Attempt to read from DS18B20 sensor
            temperature = read_ds18b20()
            if temperature is not None:
                return temperature
            else:
                raise SensorReadError("Failed to read temperature from DS18B20 sensor.")
        except SensorReadError as e:
            logging.error(f"Sensor Read Error: {e}")
            return simulate_temperature() # Fallback to simulation

def read_ds18b20():
    # This function attempts to read temperature from the DS18B20 sensor.
    # It checks for the presence of the device and reads the temperature from the w1_slave file.
    # This is a simplified implementation and may require adjustments based on your specific sensor setup.
    try:
        # Check if the DS18B20 device is present
        if not os.path.exists("/sys/bus/w1/devices/28-*/w1_slave"):
            logging.warning("DS18B20 sensor not found.  Simulating temperature.")
            return None

        # Read the temperature from the w1_slave file
        with open("/sys/bus/w1/devices/28-*/w1_slave", "r") as f:
            lines = f.readlines()
            if lines[0].strip()[-3:] == 'YES':
                equals_pos = lines[1].find('t=')
                if equals_pos != -1:
                    temp_string = lines[1][equals_pos+2:]
                    temperature = float(temp_string) / 1000.0
                    return temperature
            else:
                logging.warning("Invalid data from DS18B20 sensor.")
                return None

    except Exception as e:
        logging.error(f"Error reading DS18B20 sensor: {e}")
        return None

def simulate_temperature():
    # Simulates temperature readings between 15°C and 30°C.
    # This function provides a realistic temperature range for testing purposes.
    return random.uniform(15, 30)

def read_ph():
    if args.simulate_sensors:
        return simulate_ph()
    else:
        # Placeholder for actual PH sensor reading
        logging.warning("PH sensor not implemented. Simulating PH.")
        return simulate_ph()

def simulate_ph():
    # Simulates pH readings between 5.5 and 6.5.
    # This function provides a realistic pH range for testing purposes.
    return random.uniform(5.5, 6.5)

def read_ec():
    if args.simulate_sensors:
        return simulate_ec()
    else:
        # Placeholder for actual EC sensor reading
        logging.warning("EC sensor not implemented. Simulating EC.")
        return simulate_ec()

def simulate_ec():
    # Simulates EC readings between 1.0 and 2.0 mS/cm.
    # This function provides a realistic EC range for testing purposes.
    return random.uniform(1.0, 2.0)

def calibrate_reading(raw_value, offset, gain):
    # Calibrates the raw sensor reading using the provided offset and gain.
    # This function applies a linear calibration to the raw sensor data.
    return (raw_value - offset) * gain

def validate_reading(reading, min_value, max_value):
    # Validates the sensor reading against the specified minimum and maximum values.
    # This function checks if the reading is within the acceptable range.
    return min_value <= reading <= max_value

def log_data(timestamp, temperature, ph, ec):
    # Logs the sensor data to a CSV file.
    # This function appends the timestamp and sensor readings to the log file.
    try:
        with open("hydroponics_log.csv", "a") as f:
            f.write(f"{timestamp},{temperature},{ph},{ec}\n")
    except IOError as e:
        logging.error(f"Error writing to log file: {e}")

def handle_threshold_violation(reading, threshold, value, unit):
    # Handles threshold violations by logging a warning and blinking the alert LED.
    # This function provides a visual and audible alert when a threshold is exceeded.
    logging.warning(f"Threshold violation: {value} {unit} ({reading:.2f} {unit}) > {threshold} {unit}")
    blink_alert_led(DEFAULT_BLINK_DURATION, DEFAULT_BLINK_COUNT)

def blink_alert_led(duration, blink_count):
    # Blinks the alert LED for a specified number of cycles.
    # This function controls the GPIO pin to create a blinking effect.
    try:
        for _ in range(blink_count):
            GPIO.output(ALERT_LED_PIN, GPIO.HIGH)
            time.sleep(duration)
            GPIO.output(ALERT_LED_PIN, GPIO.LOW)
            time.sleep(duration)
    except Exception as e:
        logging.error(f"Error controlling alert LED: {e}")

# Resource Management Functions
def setup_gpio():
    # Sets up the GPIO pin for the alert LED.
    # This function configures the GPIO pin as an output.
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(ALERT_LED_PIN, GPIO.OUT)
    GPIO.output(ALERT_LED_PIN, GPIO.LOW) # Ensure LED is off initially

def cleanup_gpio():
    # Cleans up the GPIO resources.
    # This function resets the GPIO pins to their default state.
    GPIO.cleanup()

# Logging Configuration and Utilities
def setup_logging(log_level):
    # Configures the logging system.
    # This function sets up the log file and log level.
    log_formatter = logging.Formatter("%(asctime)s [%(levelname)s] %(message)s")
    log_handler = logging.handlers.TimedRotatingFileHandler(
        DEFAULT_LOG_FILE, when="midnight", interval=1, backupCount=7
    )
    log_handler.setFormatter(log_formatter)
    logger = logging.getLogger()
    logger.addHandler(log_handler)
    logger.setLevel(log_level.upper())
    return logger

# Main Program Orchestration
def main():
    global ALERT_LED_PIN
    args = parse_arguments()
    try:
        configuration = load_configuration(args.config)
        ALERT_LED_PIN = 17 # Example pin, adjust as needed
        setup_gpio()
        logger = setup_logging(DEFAULT_LOG_LEVEL)

        # Extract configuration values
        temperature_threshold = configuration["temperature_threshold"]
        ph_threshold = configuration["ph_threshold"]
        ec_threshold = configuration["ec_threshold"]
        temperature_offset = configuration["temperature_offset"]
        temperature_gain = configuration["temperature_gain"]
        ph_offset = configuration["ph_offset"]
        ph_gain = configuration["ph_gain"]
        ec_offset = configuration["ec_offset"]
        ec_gain = configuration["ec_gain"]

        logging.info("Hydroponics monitoring system started.")

        try:
            while True:
                timestamp = datetime.datetime.now().isoformat()
                temperature_raw = read_temperature()
                ph_raw = read_ph()
                ec_raw = read_ec()

                if temperature_raw is not None:
                    temperature = calibrate_reading(temperature_raw, temperature_offset, temperature_gain)
                    if validate_reading(temperature, 18, 25):
                        logging.info(f"Temperature: {temperature:.2f} °C (OK)")
                    else:
                        handle_threshold_violation(temperature, temperature_threshold, temperature_raw, "°C")
                else:
                    logging.error("Failed to read temperature.")
                    temperature = None

                if ph_raw is not None:
                    ph = calibrate_reading(ph_raw, ph_offset, ph_gain)
                    if validate_reading(ph, 5.5, 6.5):
                        logging.info(f"pH: {ph:.2f} (OK)")
                    else:
                        handle_threshold_violation(ph, ph_threshold, ph_raw, "pH")
                else:
                    logging.error("Failed to read pH.")
                    ph = None

                if ec_raw is not None:
                    ec = calibrate_reading(ec_raw, ec_offset, ec_gain)
                    if validate_reading(ec, 1.0, 2.0):
                        logging.info(f"EC: {ec:.2f} mS/cm (OK)")
                    else:
                        handle_threshold_violation(ec, ec_threshold, ec_raw, "mS/cm")
                else:
                    logging.error("Failed to read EC.")
                    ec = None

                log_data(timestamp, temperature, ph, ec)
                time.sleep(60)

        except KeyboardInterrupt:
            logging.info("Hydroponics monitoring system stopped by user.")
        except Exception as e:
            logging.error(f"An unexpected error occurred: {e}")
        finally:
            cleanup_gpio()
            logging.info("GPIO cleanup completed.")

    except ConfigurationError as e:
        logging.error(f"Configuration error: {e}")
        sys.exit(1)
    except Exception as e:
        logging.error(f"An unexpected error occurred during initialization: {e}")
        sys.exit(1)

# Entry Point
if __name__ == "__main__":
    main()

