import time
import cv2
import numpy as np

# Configuration
CAMERA_WIDTH = 64  # Reduced for faster processing
CAMERA_FRAMERATE = 15
MOTION_THRESHOLD = 10
IMAGE_PATH = 'motion.jpg'
CAPTURE_INTERVAL = 2  # seconds
BASELINE_WAIT = 2  # seconds

def initialize_camera():
    """Initializes the camera."""
    try:
        camera = cv2.VideoCapture(0)  # 0 for default camera
        if not camera.isOpened():
            raise IOError("Cannot open webcam")
        camera.set(cv2.CAP_PROP_FRAME_WIDTH, CAMERA_WIDTH)
        camera.set(cv2.CAP_PROP_FRAME_RATE, CAMERA_FRAMERATE)
        time.sleep(BASELINE_WAIT)  # Allow camera to warm up
        return camera
    except Exception as e:
        print(f"Camera initialization error: {e}")
        return None

def calculate_average_pixel_value(frame):
    """Calculates the average pixel value of a frame."""
    return np.mean(frame)

def detect_motion(camera, baseline_average):
    """Detects motion by comparing current average to baseline."""
    try:
        ret, frame = camera.read()
        if not ret:
            print("Failed to grab frame")
            return False, baseline_average

        average_pixel_value = calculate_average_pixel_value(frame)
        if abs(average_pixel_value - baseline_average) > MOTION_THRESHOLD:
            return True, average_pixel_value
        return False, baseline_average
    except Exception as e:
        print(f"Error during motion detection: {e}")
        return False, baseline_average

def save_image(frame, image_path):
    """Saves the current frame as an image."""
    try:
        cv2.imwrite(image_path, frame)
        print(f"Motion detected! Image saved to {image_path}")
    except Exception as e:
        print(f"Error saving image: {e}")

def main():
    """Main function to run the security camera system."""
    camera = initialize_camera()
    if camera is None:
        return

    baseline_average = None

    try:
        while True:
            # Warm up baseline
            if baseline_average is None:
                print("Establishing baseline...")
                for _ in range(CAPTURE_INTERVAL * CAMERA_FRAMERATE):
                    ret, frame = camera.read()
                    if not ret:
                        print("Failed to grab frame for baseline.")
                        break
                    baseline_average = calculate_average_pixel_value(frame)
                    time.sleep(1 / CAMERA_FRAMERATE)
                if baseline_average is None:
                    print("Failed to establish baseline.")
                    break
                print(f"Baseline established: {baseline_average}")
            else:
                # Motion detection loop
                motion_detected, average_pixel_value = detect_motion(camera, baseline_average)
                if motion_detected:
                    save_image(frame, IMAGE_PATH)
                    baseline_average = average_pixel_value  # Update baseline

            time.sleep(CAPTURE_INTERVAL)

    except KeyboardInterrupt:
        print("Exiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        camera.release()
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

