import cv2
import pyzbar.pyzbar as pyzbar
from datetime import datetime
import csv
import time
import threading
import os

# Define global variables
running = True
camera = None
inventory_log_file = 'inventory_log.csv'
error_log_file = 'error_log.txt'

def initialize_camera():
    """Initializes the USB camera."""
    global camera
    try:
        camera = cv2.VideoCapture(0)  # 0 is the default camera index
        if not camera.isOpened():
            raise Exception("Could not open camera")
        return True
    except Exception as e:
        log_error(f"Camera initialization failed: {e}")
        return False

def log_error(message):
    """Logs an error message to the error log file."""
    timestamp = datetime.now().isoformat()
    try:
        with open(error_log_file, 'a', newline='') as f:
            writer = csv.writer(f)
            writer.writerow([timestamp, message])
    except Exception as e:
        print(f"Error writing to error log: {e}")

def capture_and_decode():
    """Captures an image from the camera, decodes QR codes, and processes the data."""
    global running, camera
    while running:
        try:
            ret, frame = camera.read()
            if not ret:
                log_error("Failed to capture frame")
                time.sleep(1)  # Wait before retrying
                continue

            gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            decoded_objects = pyzbar.decode(gray)

            if decoded_objects:
                for obj in decoded_objects:
                    item_id = obj.data.decode('utf-8')
                    timestamp = datetime.now().isoformat()
                    validate_and_log(item_id, timestamp)
            else:
                time.sleep(0.2)  # Short delay if no QR code found

        except Exception as e:
            log_error(f"Error during capture and decoding: {e}")
            time.sleep(1)  # Wait before retrying

def validate_and_log(item_id, timestamp):
    """Validates the item ID and logs it to the inventory log file."""
    if not item_id or not item_id.isalnum():
        log_error(f"Invalid item ID: {item_id}")
        return

    try:
        with open(inventory_log_file, 'a', newline='') as f:
            writer = csv.writer(f)
            writer.writerow(['Camera 1', item_id, timestamp])
    except Exception as e:
        log_error(f"Error writing to inventory log: {e}")

def main():
    """Main function to initialize and run the QR code scanner."""
    global running

    if not initialize_camera():
        print("Failed to initialize camera. Exiting.")
        return

    try:
        while running:
            capture_and_decode()
            time.sleep(0.1)  # Keep the main thread alive
    except KeyboardInterrupt:
        print("Exiting program...")
    finally:
        running = False
        if camera:
            camera.release()
        cv2.destroyAllWindows()
        print("Camera released and windows closed.")

if __name__ == "__main__":
    main()

