class CameraStreamBuffer:
    """
    Buffers and parses an MJPEG stream from a camera.

    Attributes:
        buffer_: In-memory byte buffer for storing the MJPEG stream.
        config: Configuration object (expected to have a 'encode' attribute).
        loop: Optional event loop for asynchronous operation.
    """

    def __init__(self, config, loop=None):
        self.buffer_ = io.BytesIO()
        self.config = config
        self.loop = loop
        if self.loop:
            self.buffer_.close = self._close_callback

    def _close_callback(self):
        """Handles buffer closure, flushing content if necessary."""
        if self.buffer_.tell() > 0:
            self.flush()

    def write(self, data: bytes) -> None:
        """Writes data to the buffer, parsing and processing MJPEG frames."""
        try:
            self.buffer_.write(data)
            if self._is_complete_frame():
                self._process_frame()
        except Exception as e:
            logging.error(f"Error in CameraStreamBuffer: {e}", exc_info=True)

    def flush(self) -> Optional[bytes]:
        """Flushes the buffer and returns the complete frame data.

        Returns:
            The complete frame data as bytes, or None if no frame is complete.
        """
        if self._is_complete_frame():
            try:
                new_buffer = io.BytesIO()
                self.buffer_.seek(0)
                new_buffer.write(self.buffer_.read())
                self.buffer_.seek(0)
                self.buffer_.truncate(0)
                return new_buffer.getvalue()
            except Exception as e:
                logging.error(f"Error flushing buffer: {e}", exc_info=True)
                return None
        return None

