# temperature_monitoring_rpi.py
# Reads temperature data from a UART sensor and logs it to a CSV file.
# Designed for Raspberry Pi 5 in a smart retail context.

import serial
import time
import csv
import os

# Configuration
SERIAL_PORT = '/dev/ttyACM0'  # UART port for the temperature sensor
BAUD_RATE = 115200  # Baud rate for UART communication
TIMEOUT = 1  # Timeout for UART reads in seconds
LOG_FILE = 'temperature_log.csv'  # CSV file to store temperature data

def initialize_serial(port, baudrate, timeout):
    """Initializes the serial connection."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def read_temperature(serial_port):
    """Reads temperature data from the serial port."""
    try:
        data = serial_port.readline().decode('ascii', errors='replace').strip()
        if data:
            return float(data)
        return None
    except ValueError:
        print("Malformed data received from sensor.")
        return None
    except Exception as e:
        print(f"Error reading from serial port: {e}")
        return None

def convert_to_fahrenheit(celsius):
    """Converts Celsius to Fahrenheit."""
    return (celsius * 9/5) + 32

def log_temperature(celsius, fahrenheit, log_filepath):
    """Logs the temperature data to a CSV file."""
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    try:
        with open(log_filepath, 'a', newline='') as csvfile:
            writer = csv.writer(csvfile)
            writer.writerow([timestamp, celsius, fahrenheit])
    except Exception as e:
        print(f"Error writing to CSV file: {e}")

def main():
    """Main function to read temperature and log data."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)

    if serial_connection is None:
        print("Failed to initialize serial connection. Exiting.")
        return

    # Write header row if the file doesn't exist
    if not os.path.exists(LOG_FILE):
        try:
            with open(LOG_FILE, 'w', newline='') as csvfile:
                writer = csv.writer(csvfile)
                writer.writerow(['Timestamp', 'Temperature (C)', 'Temperature (F)'])
        except Exception as e:
            print(f"Error creating CSV file: {e}")
            serial_connection.close()
            return

    try:
        while True:
            temperature_celsius = read_temperature(serial_connection)

            if temperature_celsius is not None:
                temperature_fahrenheit = convert_to_fahrenheit(temperature_celsius)
                log_temperature(temperature_celsius, temperature_fahrenheit, LOG_FILE)
                print(f"Temperature: {temperature_celsius:.2f}C / {temperature_fahrenheit:.2f}F")
            time.sleep(1)  # Wait for 1 second

    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        serial_connection.close()
        print("Serial port closed.")

if __name__ == "__main__":
    main()

