def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        return i2c
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_sensor(i2c_bus):
    """Initialize the AHT20 sensor."""
    try:
        sensor = adafruit_ahtx0.AHTx0(i2c_bus)
        return sensor
    except Exception as e:
        print(f"Error initializing AHT20 sensor: {e}")
        return None

def read_sensor_data(sensor):
    """Read temperature and humidity from the sensor."""
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        return temperature, humidity
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None

def validate_data(temperature, humidity):
    """Validate temperature and humidity readings."""
    if temperature is None or humidity is None:
        return False
    if not -40 <= temperature <= 85:
        print(f"Warning: Temperature {temperature}°C is out of range.")
        return False
    if not 0 <= humidity <= 100:
        print(f"Warning: Humidity {humidity}% is out of range.")
        return False
    return True

def print_sensor_data(temperature, humidity):
    """Print the sensor data to the console."""
    print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} Temperature: {temperature:.1f} C Humidity: {humidity:.1f} %")

def main():
    """Main function to read and display temperature and humidity."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        print("Failed to initialize I2C. Exiting.")
        return

    sensor = initialize_sensor(i2c_bus)
    if sensor is None:
        print("Failed to initialize sensor. Exiting.")
        return

    i2c_retry_count = 0
    try:
        while True:
            temperature, humidity = read_sensor_data(sensor)

            if validate_data(temperature, humidity):
                print_sensor_data(temperature, humidity)

            time.sleep(5)

            # Basic watchdog timer - if the loop takes longer than 10 seconds to complete, print an error
            if time.time() % 10 > 8:  # Check if the loop took longer than 10 seconds
                print("Watchdog timeout! Possible sensor or I2C issue.")

    except KeyboardInterrupt:
        print("Program terminated by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Attempt to re-initialize I2C and sensor in case of mid-run disconnect
        print("Attempting to re-initialize I2C and sensor...")
        i2c_bus = initialize_i2c()
        if i2c_bus:
            sensor = initialize_sensor(i2c_bus)
            if sensor:
                print("Re-initialization successful. Continuing...")
            else:
                print("Re-initialization failed. Exiting.")
        else:
            print("Re-initialization failed. Exiting.")
        print("Exiting program.")

if __name__ == "__main__":
    main()

