import time
import board
import adafruit_dht

# Use board.D4 for DHT22 data pin
data_pin = board.D4

# Initialize DHT22 sensor
dht_device = adafruit_dht.DHT22(data_pin)

def read_dht22():
    """Reads temperature and humidity from DHT22 sensor."""
    try:
        temperature_c = dht_device.temperature
        humidity = dht_device.humidity
        return temperature_c, humidity
    except RuntimeError as error:
        # Errors happen fairly often, DHT's are hard to read, just keep going
        print(error.args[0])
        return None, None
    except Exception as error:
        dht_device.exit()
        raise error

def format_output(temperature, humidity):
    """Formats temperature and humidity into a human-readable string."""
    if temperature is not None and humidity is not None:
        return f"{time.strftime('%Y-%m-%d %H:%M:%S')} Temp: {temperature:.1f}°C Humidity: {humidity:.1f}%"
    else:
        return "Failed to read DHT22"

def main():
    """Main function to read and print DHT22 data."""
    try:
        while True:
            temperature, humidity = read_dht22()
            print(format_output(temperature, humidity))
            time.sleep(2.0)
    except KeyboardInterrupt:
        print("Exiting program")
    finally:
        dht_device.exit()

if __name__ == "__main__":
    main()

