"""
Control an LED and read a switch using the MCP23017 I2C GPIO expander.

This script demonstrates robust error handling, optimized performance, and 
hardware interaction best practices for a Raspberry Pi environment.
"""

import time
import sys
from MCP23017_I2C import GPIO_CHIP, MCP23017Error

# Constants
DEVICE_ADDRESS = 0x20
LED_PIN = 0
SWITCH_PIN = 7
I2C_BUS_NUMBER = 1  # Adjust if necessary
DEBOUNCE_INTERVAL = 0.02  # 20ms debounce

def initialize_gpio_chip(address, bus_number):
    """Initialize and configure the MCP23017 GPIO chip."""
    try:
        chip = GPIO_CHIP(address, bus_number)
        chip.setup(LED_PIN, 'OUT', 0)  # LED on GPA0, bank 0
        chip.setup(SWITCH_PIN, 'IN', 1) # Switch on GPB7, bank 1, pull-up
        return chip
    except MCP23017Error as e:
        raise RuntimeError(f"MCP23017 initialization failed: {e}")


def read_switch_state(chip):
    """Read and debounce the switch state."""
    try:
        state = chip.input(SWITCH_PIN, 1)
        # Debounce: require two consecutive readings
        time.sleep(DEBOUNCE_INTERVAL)
        new_state = chip.input(SWITCH_PIN, 1)
        if new_state == state:
            return new_state
        else:
            # Switch state changed during debounce; re-read
            time.sleep(DEBOUNCE_INTERVAL)  # Avoid racing conditions
            return chip.input(SWITCH_PIN, 1)
    except MCP23017Error as e:
        raise RuntimeError(f"Error reading switch state: {e}")


def control_led(chip, state):
    """Control the LED state."""
    try:
        chip.output(LED_PIN, state, 0)
    except MCP23017Error as e:
        raise RuntimeError(f"Error controlling LED: {e}")


def main():
    """Main function to control the LED and read the switch."""
    try:
        gpio_chip = initialize_gpio_chip(DEVICE_ADDRESS, I2C_BUS_NUMBER)

        print("MCP23017 LED and Switch Control (Ctrl+C to exit)")
        print("(Current state: LED OFF, Switch INPUT)")

        while True:
            try:
                switch_state = read_switch_state(gpio_chip)
                if switch_state == 1:
                    control_led(gpio_chip, 1)  # Turn LED ON
                    print("LED ON")
                else:
                    control_led(gpio_chip, 0)  # Turn LED OFF
                    print("LED OFF")

                time.sleep(0.1)

            except RuntimeError as e:
                print(f"Error: {e}")
                break  # Exit on error

    except RuntimeError as e:
        print(f"Fatal Error: {e}")
        sys.exit(1) # Indicate an error occurred

    finally:
        # Ensure GPIO chip is closed on exit (although not strictly needed here)
        if 'gpio_chip' in locals() and gpio_chip.is_initialized():
            gpio_chip.close()


if __name__ == "__main__":
    main()

