import RPi.GPIO as GPIO
import time
import signal
import sys

# Define sensor pins using BCM numbering
SENSOR_PINS = [17, 27, 22]

# Define poll interval in seconds
POLL_INTERVAL = 1

# Global variable to track program state
running = True

def signal_handler(sig, frame):
    """Handles SIGTERM signal for graceful shutdown."""
    global running
    print("Received shutdown signal. Exiting gracefully...")
    running = False

def initialize_gpio(pins):
    """Initializes GPIO pins as input with pull-up resistors."""
    try:
        GPIO.setmode(GPIO.BCM)
        for pin in pins:
            GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        print(f"GPIO pins initialized: {pins}")
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        sys.exit(1)

def read_sensor(pin):
    """Reads the state of a single sensor pin."""
    try:
        return GPIO.input(pin)
    except Exception as e:
        print(f"Error reading sensor on pin {pin}: {e}")
        return None

def process_sensor_data(sensor_data):
    """Processes sensor data and prints responses based on sensor state."""
    if sensor_data[0] == GPIO.HIGH:
        print('Response for sensor 1')
    if sensor_data[1] == GPIO.HIGH:
        print('Response for sensor 2')
    if sensor_data[2] == GPIO.HIGH:
        print('Response for sensor 3')

def main_loop():
    """Main loop to continuously poll sensors and process data."""
    global running
    try:
        while running:
            sensor_data = [read_sensor(pin) for pin in SENSOR_PINS]
            if all(val is not None for val in sensor_data):
                process_sensor_data(sensor_data)
            time.sleep(POLL_INTERVAL)
    except KeyboardInterrupt:
        print("Program interrupted by user.")
    finally:
        GPIO.cleanup()
        print("GPIO resources released.")

if __name__ == "__main__":
    # Register signal handler for graceful shutdown
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize GPIO pins
    initialize_gpio(SENSOR_PINS)

    # Print startup message
    print(f"Monitoring sensors on pins {SENSOR_PINS} with {POLL_INTERVAL}-second interval.")

    # Start the main loop
    main_loop()

