PASSWORD = 'your_password'  # Replace with your actual password
POLLING_INTERVAL_SECONDS = 5  # Time interval between sensor readings

def initialize_gpio(pin):
    """Initializes the GPIO pin for the digital sensor."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
    return pin

def read_sensor_value(pin):
    """Reads the current state of the digital sensor connected to the specified GPIO pin."""
    return GPIO.input(pin)

def create_payload(sensor_type, sensor_value):
    """Creates a JSON payload containing sensor data."""
    return {'sensor': sensor_type, 'value': sensor_value}

def submit_data(url, payload, username, password):
    """Submits the sensor data to the server using HTTP POST with Basic Authentication."""
    try:
        response = requests.post(url, json=payload, auth=HTTPBasicAuth(username, password))
        response.raise_for_status()  # Raise HTTPError for bad responses (4xx or 5xx)
        print(f"Server response: {response.status_code} - {response.text}")
    except requests.RequestException as e:
        print(f"Error submitting data: {e}")

def main():
    """Main function to continuously read sensor data and submit it to the server."""
    try:
        gpio_pin = initialize_gpio(SENSOR_GPIO_PIN)
        while True:
            try:
                sensor_reading = read_sensor_value(gpio_pin)
                data = create_payload('digital_input', sensor_reading)
                submit_data(SERVER_ENDPOINT, data, USERNAME, PASSWORD)
                time.sleep(POLLING_INTERVAL_SECONDS)
            except Exception as e:
                print(f"An error occurred during the process: {e}")
                time.sleep(POLLING_INTERVAL_SECONDS)  # Wait before retrying
    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        GPIO.cleanup()  # Clean up GPIO settings
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

