import threading
import RPi.GPIO as GPIO
import DOGProtocol as DOG  # Assuming this is your custom protocol library

# Constants
DEFAULT_LOG_FILE = "data.log"
POLL_INTERVAL = 0.1  # Seconds

# GPIO Setup (Safe Mode)
GPIO.setmode(GPIO.BCM)
GPIO.setwarnings(False)  # Disable warnings (use with caution)

# Global State
data_file = None
data_file_object = None
receive_thread = None
dog_running = False

# Signal Handler for Clean Exit
def signal_handler(sig, frame):
    print("\nExiting gracefully...")
    global dog_running, receive_thread
    dog_running = False
    if receive_thread:
        receive_thread.join(timeout=2)  # Wait for thread to finish
    DOG.deinit()
    GPIO.cleanup()
    sys.exit(0)

# Register Signal Handlers
signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)


class DOGServer:
    def __init__(self):
        self.log_file = DEFAULT_LOG_FILE
        self.is_running = False
        self.received_data = ""

    def start(self, log_file=DEFAULT_LOG_FILE):
        """Starts the DOG server."""
        global data_file, data_file_object, receive_thread, dog_running
        if self.is_running:
            print("Server already running.")
            return

        if log_file:
            self.log_file = log_file

        try:
            data_file = self.log_file
            data_file_object = open(data_file, 'a')
        except Exception as e:
            print(f"Error opening log file: {e}")
            return

        self.is_running = True
        dog_running = True # Global flag to control DOG operations

        receive_thread = threading.Thread(target=self.receive_data)
        receive_thread.daemon = True # Allow program to exit if thread is blocked
        receive_thread.start()

        print(f"Server started. Logging to: {self.log_file}")


    def stop(self):
        """Stops the DOG server."""
        global dog_running
        dog_running = False
        if receive_thread:
            receive_thread.join()
        self.close()


    def close(self):
        """Closes resources."""
        global data_file_object
        if data_file_object:
            try:
                data_file_object.close()
            except Exception as e:
                print(f"Error closing log file: {e}")
        self.is_running = False
        print("Server stopped.")


    def receive_data(self):
        """Continuously receives and logs data."""
        while dog_running: # Check global flag
            try:
                received_data = DOG.receive() # Call your custom receive function
                if received_data:
                    try:
                        data_file_object.write(received_data + "\n")
                        data_file_object.flush() # Ensure data is written immediately
                    except Exception as e:
                        print(f"Error writing to log file: {e}")
            except Exception as e:
                print(f"Error in data reception: {e}")
                dog_running = False # Set flag to stop loop if an error occurs
            time.sleep(POLL_INTERVAL)


    def display(self):
        """Displays the contents of the log file."""
        try:
            with open(self.log_file, 'r') as f:
                print(f.read())
        except Exception as e:
            print(f"Error reading log file: {e}")


    def write(self, data):
        """Writes data directly to the log file."""
        try:
            data_file_object.write(data + "\n")
            data_file_object.flush()
        except Exception as e:
            print(f"Error writing to log file: {e}")



    def send(self, data):
        """Sends data using DOG.send()."""
        if not self.is_running:
            print("Server not running. Start the server first.")
            return
        try:
            DOG.send(data_string=data) # Pass your custom data string
            print(f"Sent: {data}")
        except Exception as e:
            print(f"Error sending data: {e}")


    def help(self):
        """Displays help information."""
        print("\nAvailable commands:")
        print("  start <log_file>: Start the server, logging to the specified file.")
        print("  stop: Stop the server.")
        print("  display: Display the contents of the log file.")
        print("  write <data>: Write data directly to the log file.")
        print("  send <data>: Send data using DOG.send().")
        print("  help [command]: Display help information (optional command).")
        print("  exit: Exit the program.\n")


# Main Program
if __name__ == "__main__":
    server = DOGServer()
    server.help()

    try:
        while True:
            command = input("JAYES@ROVER53:\t").strip().split()

            if not command:
                continue

            if command[0] == "start":
                if len(command) > 1:
                    server.start(log_file=command[1])
                else:
                    server.start()

            elif command[0] == "stop":
                server.stop()

            elif command[0] == "display":
                server.display()

            elif command[0] == "write":
                if len(command) > 1:
                    server.write(" ".join(command[1:])) # Join arguments for data string
                else:
                    server.write(input("Enter data to write: ").strip())

            elif command[0] == "send":
                if len(command) > 1:
                    server.send(" ".join(command[1:])) # Join arguments for data string
                else:
                    server.send(input("Enter data to send: ").strip())

            elif command[0] == "help":
                if len(command) > 1:
                    server.help(command[1])
                else:
                    server.help()

            elif command[0] == "exit":
                server.stop()  # Stop the server before exiting
                break

            else:
                print("Invalid command. Type 'help' for available commands.")


    except KeyboardInterrupt:
        print("\nKeyboard interrupt detected. Exiting...")
        server.stop() # Ensure server is stopped before exiting
        break

