    """Set up the GPIO pin with a pull-up resistor."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)

def check_power_status(pin):
    """Read the voltage sensor pin and return True if power is present, False otherwise."""
    return GPIO.input(pin) == GPIO.HIGH

def send_power_failure_alert(url):
