    try:
        requests.post(url, json={'alert': 'Power failure detected'}, timeout=5)
    except requests.RequestException as e:
        print(f"Alert failed: {e}")

def main():
    """Main function to continuously monitor the power status."""
    initialize_gpio(VOLTAGE_SENSOR_PIN)

    try:
        while True:
            if check_power_status(VOLTAGE_SENSOR_PIN):
                print("Power is present")
            else:
                print("Power failure detected!")
                send_power_failure_alert(ALERT_ENDPOINT)
            time.sleep(1)
    except KeyboardInterrupt:
        print("Exiting program")
    finally:
        GPIO.cleanup()
        print("GPIO cleanup complete")

if __name__ == "__main__":
    main()

