    """Reads the value from the specified sensor pin."""
    try:
        return GPIO.input(pin)
    except Exception as e:
        print(f"Error reading sensor on pin {pin}: {e}")
        return None  # Return None to indicate an error

def determine_steering(left_value, right_value):
    """Determines the steering direction based on sensor values."""
    if left_value == 0 and right_value == 0:
        return "forward"
    elif left_value == 0 and right_value == 1:
        return "turn_right"
    elif left_value == 1 and right_value == 0:
        return "turn_left"
    else:
        return "search"

