import RPi.GPIO as GPIO
import time
import logging
import os
import signal
import sys

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Constants for GPIO pin numbers (BCM numbering)
DATA_OUT_PIN = 5
TIMER_OUT_PIN = 6
START_SIGNAL = [1, 0, 1, 1, 1, 1, 1, 1]
END_SIGNAL = [1, 1, 1, 1, 1, 1, 1, 1]
DATA_IN_PIN = 20
TIMER_IN_PIN = 21

# Constants for protocol parameters
TRANSMIT_DELAY = 0.0005  # Delay between bit transmissions (seconds)
RECEPTION_TIMEOUT = 1  # Maximum time to receive data (seconds)


class GPIOError(Exception):
    """Custom exception for GPIO related errors."""
    pass


class ProtocolError(Exception):
    """Custom exception for data protocol errors."""
    pass


def setup_gpio():
    """Initializes GPIO settings. Uses BCM numbering and disables warnings."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
    except Exception as e:
        raise GPIOError(f"GPIO setup failed: {e}") from e


def cleanup_gpio():
    """Resets GPIO configuration."""
    GPIO.cleanup()


def char_to_bits(char: str) -> list[int]:
    """Converts a character to a list of bits (0 or 1)."""
    if not isinstance(char, str) or len(char) != 1:
        raise TypeError("Input must be a single character string.")

    ascii_value = ord(char)
    return [0] * 7 + [int(bit) for bit in bin(ascii_value)[2:].zfill(7)]


def bits_to_char(bits: list[int]) -> str:
    """Converts a list of bits to a character."""
    if not isinstance(bits, list) or not all(isinstance(bit, int) for bit in bits):
        raise TypeError("Input must be a list of integers.")

    if len(bits) != 8:
        raise ValueError("Input list must contain 8 bits.")

    return chr(int("".join(map(str, bits[7:])), 2))


def string_to_bits_list(input_string: str) -> list[list[int]]:
    """Converts a string to a list of bit lists."""
    if not isinstance(input_string, str):
        raise TypeError("Input must be a string.")
    return [char_to_bits(char) for char in input_string]


def bits_list_to_string(bits_lists: list[list[int]]) -> str:
    """Converts a list of bit lists back to a string."""
    if not isinstance(bits_lists, list):
        raise TypeError("Input must be a list.")
    return "".join(bits_to_char(bits) for bits in bits_lists if bits not in (START_SIGNAL, END_SIGNAL))


def transmit_bit(bit: int, data_pin: int, timer_pin: int, delay: float):
    """Transmits a single bit."""
    if bit not in (0, 1):
        raise ValueError("Bit must be 0 or 1.")

    GPIO.output(timer_pin, GPIO.LOW)
    GPIO.output(data_pin, bit)
    time.sleep(delay)
    GPIO.output(timer_pin, GPIO.HIGH)
    time.sleep(delay)
    GPIO.output(timer_pin, GPIO.LOW)


def send_data(data_string: str, data_pin: int, timer_pin: int, delay: float):
    """Sends a string of data over the GPIO pins."""
    if not isinstance(data_string, str):
        raise TypeError("Input must be a string.")

    try:
        setup_gpio()
        GPIO.setup(data_pin, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(timer_pin, GPIO.OUT, initial=GPIO.LOW)

        for bits_list in [START_SIGNAL] + string_to_bits_list(data_string) + [END_SIGNAL]:
            for bit in bits_list:
                transmit_bit(bit, data_pin, timer_pin, delay)

        logger.info(f"Sent data: {data_string}")

    except Exception as e:
        raise ProtocolError(f"Data transmission failed: {e}") from e
    finally:
        cleanup_gpio()



def receive_bit(data_pin: int, timer_pin: int, timeout: float) -> int:
    """Receives a single bit with timeout."""
    if not isinstance(data_pin, int) or not isinstance(timer_pin, int) or not isinstance(timeout, (int, float)):
        raise TypeError("Pin numbers and timeout must be numbers.")

    start_time = time.time()
    while GPIO.input(timer_pin) == GPIO.LOW:
        if time.time() - start_time > timeout:
            raise TimeoutError("Timeout waiting for bit.")
        continue

    return GPIO.input(data_pin)


def receive_data(data_pin: int, timer_pin: int, timeout: float) -> str:
    """Receives data from the GPIO pins."""
    if not isinstance(data_pin, int) or not isinstance(timer_pin, int) or not isinstance(timeout, (int, float)):
        raise TypeError("Pin numbers and timeout must be numbers.")

    try:
        setup_gpio()
        GPIO.setup(data_pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        GPIO.setup(timer_pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)

        received_bits = []
        current_bit_index = 0
        start_time = time.time()

        while True:
            if time.time() - start_time > timeout:
                raise TimeoutError("Timeout during data reception.")

            received_bits.append(receive_bit(data_pin, timer_pin, timeout))

            if current_bit_index == 8:
                if not received_bits == END_SIGNAL:
                    raise ProtocolError("End signal not received.")
                break

            current_bit_index += 1


        return bits_list_to_string(received_bits)

    except Exception as e:
        raise ProtocolError(f"Data reception failed: {e}") from e
    finally:
        cleanup_gpio()


def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""
    logger.info('Exiting gracefully...')
    sys.exit(0)


def main():
    """Main function to demonstrate data transmission and reception."""
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    data_to_send = "Hello, this is a test!"
    try:
        send_data(data_to_send, DATA_OUT_PIN, TIMER_OUT_PIN, TRANSMIT_DELAY)
        received_data = receive_data(DATA_IN_PIN, TIMER_IN_PIN, RECEPTION_TIMEOUT)
        logger.info(f"Received data: {received_data}")
    except (GPIOError, ProtocolError) as e:
        logger.error(f"An error occurred: {e}")


if __name__ == "__main__":
    main()

