            GPIO.output(pin, GPIO.LOW)   # Turn dynamo off
            time.sleep(duration)          # Wait
    except KeyboardInterrupt:
        print("Dynamo stopped by user.")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        GPIO.cleanup()  # Clean up GPIO settings

