            elif action in ('PAUSE', 'RESTART'):
                self._pause_channel(command)
            elif action in ('PAUSE_ALL', 'RESTART_ALL'):
                self._pause_all_channels(command)
            elif action in ('SET_PPM', 'SET_YAW', 'SET_ROL', 'SET_ROI'):  # DAC control
                self._set_dac_value(command)
            elif action in ('SET_PPM_STR', 'SET_YAW_STR', 'SET_ROL_STR', 'SET_ROI_STR'): # String DAC control
                self._set_dac_value_string(command)
            elif action in ('SET_PWM', 'SET_SPEED'):  # PWM control
                self._set_pwm_value(command)
            else:
