        except KeyError as e:
            self.logger.error(f"Missing key in command: {e}")
        except Exception as e:
            self.logger.exception(f"Error handling command: {e}")

    def _subscribe(self, command):
        """Subscribes to a data stream."""
        stream_filter = command['stream_filter']
        channel_id = command['channel_id']
        callback_info = command['callback']

        if not all(key in command for key in ('stream_filter', 'channel_id', 'callback')):
            self.logger.error("Incomplete subscription information.")
            return

        if stream_filter not in self.subscriptions:
            self.subscriptions[stream_filter] = []
            try:
                self.subscribed_sockets[stream_filter] = [self.subscriber_socket]  # Initialize with master socket
                self.subscriber_socket.setsockopt_string(zmq.SUBSCRIBE, stream_filter)
            except Exception as e:
                self.logger.error(f"Error subscribing to {stream_filter}: {e}")
                return

        self.subscriptions[stream_filter].append({
            'callback': callback_info,
            'kwargs': command.get('kwargs', {}),
            'state': {},
            'control': {'alert': True, 'pause': False},
            'channel_id': channel_id
        })

        self.channel_info[channel_id] = {
            'kwargs': command.get('kwargs', {}),
            'state': {},
            'control': {'alert': True, 'pause': False}
        }

