        """Initializes the GPIO pin for PWM output with error handling."""
        try:
            GPIO.setmode(GPIO.BOARD)
            GPIO.setup(12, GPIO.OUT)
            self.pwm = GPIO.PWM(12, 1000)  # 1000 Hz frequency
            self.pwm.start(0.0)
            self.logger.info("Initialized GPIO pin 12 for PWM output.")
        except Exception as e:
            self.logger.exception(f"Failed to initialize GPIO pin 12: {e}")
            raise  # Re-raise the exception to be handled at a higher level

    def set_pwm_value(self, value):
        """Sets the PWM duty cycle for error signal generation."""
        try:
            if not -1.0 <= value <= 1.0:
                raise ValueError("PWM value must be within the range [-1.0, 1.0].")

            self.pwm.ChangeDutyCycle(abs(value))
            self.last_output = float(abs(value))
            self.logger.debug(f"Set PWM duty cycle to {value}")

        except ValueError as e:
            self.logger.error(f"Invalid PWM value: {e}")
        except Exception as e:
            self.logger.exception(f"Error setting PWM value: {e}")

    def update_error_output(self, error):
        """
        Updates the error output based on the PID controller result.

        Args:
            error (float): The current error value.
        """
        try:
            now = time.time()
            dt = now - self.last_time

            if dt >= self.delay:
                # Compute PID terms
                p_term = self.p * error
                i_term = self.i * (error + self.last_error) / 2.0  # Trapezoidal integration
                d_term = self.d * (error - self.last_error) / dt

                # Compute output
                output = p_term + i_term + d_term

                # Limit output to [-1.0, 1.0]
                self.last_output = max(-1.0, min(1.0, output))

                # Update last error
                self.last_error = error

                # Set PWM duty cycle
                self.set_pwm_value(self.last_output)

                self.last_time = now

                self.logger.debug(f"PID output: {self.last_output}, Error: {error}")

        except Exception as e:
            self.logger.exception(f"Error updating error output: {e}")

    def set_pid_parameters(self, p, i, d):
        """Sets the PID parameters."""
        try:
            self.p = p
            self.i = i
            self.d = d
            self.logger.info(f"Set PID parameters: P={p}, I={i}, D={d}")
        except Exception as e:
            self.logger.error(f"Error setting PID parameters: {e}")

    def cleanup_gpio(self):
        """Stops the PWM and cleans up the GPIO pin."""
        try:
            if self.pwm:
                self.pwm.stop()
