        Args:
            command (dict): The command to execute.
            config_store (dict): A dictionary to store configuration parameters.
        """
        self.config = config_store  # Update config with current store
        action = command.get('action')

        if not action:
            self.logger.error("Command received without 'action' key.")
            return

        try:
            if action == 'SUBSCRIBE':
                self._subscribe(command)
            elif action == 'UPDATE_KW':
                self._update_keywords(command)
            elif action == 'UNSUBSCRIBE':
                self._unsubscribe(command)
            elif action == 'RESET':
                self._reset_channel(command)
            elif action == 'RESET_ALL':
                self._reset_all_channels(command)
            elif action in ('MUTE', 'UNMUTE'):
                self._mute_channel(command)
            elif action in ('MUTE_ALL', 'UNMUTE_ALL'):
                self._mute_all_channels(command)
            elif action in ('PAUSE', 'RESTART'):
                self._pause_channel(command)
            elif action in ('PAUSE_ALL', 'RESTART_ALL'):
                self._pause_all_channels(command)
            elif action in ('SET_PPM', 'SET_YAW', 'SET_ROL', 'SET_ROI'):  # DAC control
                self._set_dac_value(command)
            elif action in ('SET_PPM_STR', 'SET_YAW_STR', 'SET_ROL_STR', 'SET_ROI_STR'): # String DAC control
                self._set_dac_value_string(command)
            elif action in ('SET_PWM', 'SET_SPEED'):  # PWM control
                self._set_pwm_value(command)
            else:
                self.logger.warning(f"Unknown action: {action}")

        except KeyError as e:
            self.logger.error(f"Missing key in command: {e}")
        except Exception as e:
            self.logger.exception(f"Error handling command: {e}")

    def _subscribe(self, command):
        """Subscribes to a data stream."""
        stream_filter = command['stream_filter']
        channel_id = command['channel_id']
        callback_info = command['callback']

        if not all(key in command for key in ('stream_filter', 'channel_id', 'callback')):
            self.logger.error("Incomplete subscription information.")
            return

        if stream_filter not in self.subscriptions:
            self.subscriptions[stream_filter] = []
            try:
                self.subscribed_sockets[stream_filter] = [self.subscriber_socket]  # Initialize with master socket
                self.subscriber_socket.setsockopt_string(zmq.SUBSCRIBE, stream_filter)
            except Exception as e:
                self.logger.error(f"Error subscribing to {stream_filter}: {e}")
                return

        self.subscriptions[stream_filter].append({
            'callback': callback_info,
            'kwargs': command.get('kwargs', {}),
            'state': {},
            'control': {'alert': True, 'pause': False},
            'channel_id': channel_id
        })

        self.channel_info[channel_id] = {
            'kwargs': command.get('kwargs', {}),
            'state': {},
            'control': {'alert': True, 'pause': False}
        }

        self.logger.info(f"Subscribed to: {stream_filter}, channel_id: {channel_id}")

    def _unsubscribe(self, command):
        """Unsubscribes from a data stream."""
        stream_filter = command['stream_filter']

        if stream_filter not in self.subscriptions:
            self.logger.warning(f"Not subscribed to {stream_filter}")
            return

        try:
            self.subscriber_socket.setsockopt_string(zmq.UNSUBSCRIBE, stream_filter)
            del self.subscriptions[stream_filter]
            del self.subscribed_sockets[stream_filter]
            self.logger.info(f"Unsubscribed from: {stream_filter}")
        except Exception as e:
            self.logger.error(f"Error unsubscribing from {stream_filter}: {e}")

    def _update_keywords(self, command):
        """Updates keywords for a specific channel."""
        stream_filter = command['stream_filter']
        channel_id = command['channel_id']

        if stream_filter not in self.subscriptions:
            self.logger.warning(f"Not subscribed to {stream_filter}")
            return

        for callback_info in self.subscriptions[stream_filter]:
            if callback_info['channel_id'] == channel_id:
                callback_info['kwargs'] = command.get('kwargs', {})
                self.channel_info[channel_id]['kwargs'] = command.get('kwargs', {})
                self.logger.info(f"Updated keywords for channel {channel_id} on {stream_filter}")
                break
        else:
            self.logger.warning(f"Channel {channel_id} not found on {stream_filter}")

