import time
import board
import busio
import adafruit_tsl2561
import RPi.GPIO as GPIO

# Define GPIO pin for LED
LED_PIN = 18

# Define PWM frequency
PWM_FREQUENCY = 1000  # Hz

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_light_sensor(i2c_bus):
    """Initialize the TSL2561 light sensor."""
    try:
        return adafruit_tsl2561.TSL2561(i2c_bus)
    except Exception as e:
        print(f"Error initializing TSL2561 sensor: {e}")
        return None

def initialize_gpio(led_pin, pwm_frequency):
    """Initialize GPIO for LED control with PWM."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(led_pin, GPIO.OUT)
        pwm = GPIO.PWM(led_pin, pwm_frequency)
        pwm.start(0)  # Start PWM with 0% duty cycle
        return pwm
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        return None

def read_light_level(sensor):
    """Read the ambient light level from the sensor."""
    try:
        return sensor.lux
    except Exception as e:
        print(f"Error reading light level: {e}")
        return None

def control_led_brightness(pwm, light_level):
    """Adjust the LED brightness based on the measured light level."""
    try:
        if light_level is not None:
            duty_cycle = min(100, max(0, (light_level / 10)))  # Proportional control
            pwm.ChangeDutyCycle(duty_cycle)
    except Exception as e:
        print(f"Error controlling LED brightness: {e}")

def main():
    """Main function to read light and control LED brightness."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    light_sensor = initialize_light_sensor(i2c_bus)
    if light_sensor is None:
        i2c_bus.deinit()
        return

    pwm_led = initialize_gpio(LED_PIN, PWM_FREQUENCY)
    if pwm_led is None:
        i2c_bus.deinit()
        return

    try:
        while True:
            light_level = read_light_level(light_sensor)
            control_led_brightness(pwm_led, light_level)
            time.sleep(1)
    except KeyboardInterrupt:
        print("Exiting program")
    finally:
        # Cleanup resources
        pwm_led.stop()
        GPIO.cleanup()
        i2c_bus.deinit()
        print("GPIO and I2C cleaned up.")

if __name__ == "__main__":
    main()

