import RPi.GPIO as GPIO

class MotorError(Exception):
    """Custom exception for motor-related errors."""
    pass

class Motor:
    """
    Controls a DC motor via an L298N motor driver.

    Attributes:
        driver (object): The L298N driver instance.
        pin (int): The BCM pin connected to the motor driver.
        frequency (int): The PWM frequency in Hz.
        duty_cycle (int): The current duty cycle (0-255).
    """

    def __init__(self, driver, pin, frequency=1000):
        """
        Initializes the motor.

        Args:
            driver (object): The L298N driver instance.
            pin (int): The BCM pin connected to the motor driver.
            frequency (int): The PWM frequency in Hz.
        """
        if not isinstance(driver, object) or not hasattr(driver, 'set_pwm_frequency'):
            raise MotorError("Invalid motor driver provided.")

        if not isinstance(pin, int):
            raise MotorError("Invalid GPIO pin provided.")

        self.driver = driver
        self.pin = pin
        self.frequency(frequency)  # Set initial frequency
        self.duty_cycle(0) # Start with the motor stopped

    def __del__(self):
        """Releases resources when the object is deleted."""
        self.stop()


    def set_frequency(self, frequency):
        """Sets the PWM frequency."""
        if not isinstance(frequency, int) or frequency <= 0:
            raise MotorError("Invalid frequency specified.")
        try:
            self.driver.set_pwm_frequency(self.pin, frequency)
            self.frequency = frequency
        except Exception as e:
            raise MotorError(f"Failed to set frequency: {e}")

    def set_duty_cycle(self, duty_cycle):
        """Sets the motor's duty cycle."""
        if not isinstance(duty_cycle, int) or not 0 <= duty_cycle <= 255:
            raise MotorError("Duty cycle must be an integer between 0 and 255.")
        try:
            self.driver.set_pwm_duty_cycle(self.pin, duty_cycle)
            self.duty_cycle = duty_cycle
        except Exception as e:
            raise MotorError(f"Failed to set duty cycle: {e}")


    def stop(self):
        """Stops the motor."""
        self.duty_cycle(0)

    def close(self):
        """Stops the motor and releases resources."""
        self.stop()

    def get_status(self):
        """Returns the current status of the motor."""
        return {
            "frequency": self.frequency,
            "duty_cycle": self.duty_cycle,
        }

