import time
from adafruit_servokit import ServoKit

# Constants for servo control
NUM_SERVOS = 16
DEFAULT_SERVO_CHANNEL = 0
SERVO_MIN_ANGLE = 0
SERVO_MAX_ANGLE = 180
SERVO_STEP_SIZE = 5
SERVO_DELAY = 0.04

def initialize_servo_kit():
    """Initializes the ServoKit with error handling."""
    try:
        kit = ServoKit(channels=NUM_SERVOS)
        return kit
    except OSError as e:
        print(f"Error initializing ServoKit: {e}")
        return None

def validate_servo_parameters(channel, angle):
    """Validates servo channel and angle parameters."""
    if not 0 <= channel < NUM_SERVOS:
        print(f"Invalid servo channel: {channel}. Must be between 0 and {NUM_SERVOS - 1}.")
        return False
    if not SERVO_MIN_ANGLE <= angle <= SERVO_MAX_ANGLE:
        print(f"Invalid angle: {angle}. Must be between {SERVO_MIN_ANGLE} and {SERVO_MAX_ANGLE}.")
        return False
    return True

def move_servo(kit, channel, angle):
    """Moves a servo to a specific angle with error handling and smoothing."""
    if not validate_servo_parameters(channel, angle):
        return

    try:
        kit.servo[channel].angle = angle
    except OSError as e:
        print(f"Error moving servo on channel {channel}: {e}")

def move_servo_smooth(kit, channel, target_angle):
    """Moves a servo smoothly to a target angle in steps."""
    current_angle = kit.servo[channel].angle or SERVO_MIN_ANGLE  # Handle potential None value

    if target_angle > current_angle:
        angle_range = range(int(current_angle), int(target_angle), SERVO_STEP_SIZE)
    else:
        angle_range = reversed(range(int(target_angle), int(current_angle), -SERVO_STEP_SIZE))

    for angle in angle_range:
        move_servo(kit, channel, angle)
        time.sleep(SERVO_DELAY)
    move_servo(kit, channel, target_angle) # Ensure final angle is set


def grab_object(kit):
    """Closes the gripper."""
    move_servo_smooth(kit, DEFAULT_SERVO_CHANNEL, SERVO_MAX_ANGLE)

def release_object(kit):
    """Opens the gripper."""
    move_servo_smooth(kit, DEFAULT_SERVO_CHANNEL, SERVO_MIN_ANGLE)

def perform_gripper_actions(kit, actions):
    """Executes a sequence of gripper actions."""
    for action in actions:
        if action == "grab":
            grab_object(kit)
        elif action == "release":
            release_object(kit)
        else:
            print(f"Unknown action: {action}")
            continue # Skip unknown actions


def main():
    """Main function to demonstrate servo control."""
    kit = initialize_servo_kit()
    if kit is None:
        return

    try:
        gripper_actions = ["grab", "release", "grab"]
        perform_gripper_actions(kit, gripper_actions)

    except KeyboardInterrupt:
        print("Program interrupted by user.")
    finally:
        # No explicit cleanup needed for ServoKit in this case, resources are released on exit.
        print("Exiting program.")

if __name__ == "__main__":
    main()

