KNOWN_PHRASES = {
    "turn on the pump": "pump_on",
    "turn off the pump": "pump_off",
    "switch the light on": "light_on",
    "switch the light off": "light_off"
}

def parse_intent(phrases):
    """Parses phrases to determine the intended action."""
    phrases = phrases.lower()
    for phrase, intent in KNOWN_PHRASES.items():
        if phrase in phrases:
            logging.info(f"Parsed phrase '{phrases}' as intent '{intent}'")
            return intent
    return None

def control_pump(state):
    """Controls the nutrient pump."""
    try:
        if state == "on":
            GPIO.output(PUMP_PIN, GPIO.HIGH)
            logging.info("Nutrient pump turned ON")
        elif state == "off":
            GPIO.output(PUMP_PIN, GPIO.LOW)
            logging.info("Nutrient pump turned OFF")
    except Exception as e:
        logging.error(f"Error controlling pump: {e}")

def control_light(state):
    """Controls the grow light."""
    try:
        if state == "on":
            GPIO.output(LIGHT_PIN, GPIO.HIGH)
            logging.info("Grow light turned ON")
        elif state == "off":
            GPIO.output(LIGHT_PIN, GPIO.LOW)
            logging.info("Grow light turned OFF")
    except Exception as e:
        logging.error(f"Error controlling light: {e}")

def main():
    """Main function to handle user input and control actuators."""
    try:
        # Set GPIO numbering mode
        GPIO.setmode(GPIO.BCM)
        # Setup GPIO pins as output
        GPIO.setup(PUMP_PIN, GPIO.OUT)
        GPIO.setup(LIGHT_PIN, GPIO.OUT)

        while True:
            user_input = input("Enter command (or 'exit'): ")
            if user_input.lower() == "exit":
                break

            intent = parse_intent(user_input)
            if intent == "pump_on":
                control_pump("on")
            elif intent == "pump_off":
                control_pump("off")
            elif intent == "light_on":
                control_light("on")
            elif intent == "light_off":
                control_light("off")
            else:
                logging.warning(f"Unknown command: '{user_input}'")
                # No action taken for unknown commands

    except KeyboardInterrupt:
        logging.info("Exiting program due to keyboard interrupt.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        # Ensure GPIO pins are cleaned up on exit
        GPIO.cleanup()
        logging.info("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

