import smbus
import contextlib

def _convert_to_int(value, length):
    """Convert a value to the appropriate integer representation based on length."""
    if length == 8:
        return int(value)
    elif length == 16:
        return int.from_bytes(value, byteorder='big')
    else:
        raise ValueError("Unsupported register length")


def _create_i2c_device(address, bus_number=1, length=8, debug=False):
    """Creates and returns a context manager for I2C device interaction."""
    try:
        bus = smbus.SMBus(bus_number)
    except Exception as e:
        raise RuntimeError(f"Failed to initialize I2C bus: {e}")

    @contextlib.contextmanager
    def i2c_context():
        """Context manager for I2C communication."""
        try:
            if debug:
                print(f"Attempting to communicate with I2C device at address {address}")
            bus.write_byte(address, 0x12 if length == 8 else 0x10)  # Probe for device presence
            bus.wait_i2c_device(address)  # Ensure device acknowledges
            yield bus
        finally:
            bus.close()

    return i2c_context()


def _write_register_value(bus, address, register, value, length):
    """Writes a value to a register on the I2C device."""
    try:
        if length == 8:
            bus.write_byte_data(address, register, value)
        elif length == 16:
            bus.write_word_data(address, register, _convert_to_int(value, length))
        else:
            raise ValueError("Unsupported register length")
    except Exception as e:
        raise RuntimeError(f"Failed to write to register {register}: {e}")



def _read_register_value(bus, address, register, length):
    """Reads a value from a register on the I2C device."""
    try:
        if length == 8:
            return bus.read_byte_data(address, register)
        elif length == 16:
            return _convert_to_int(bus.read_word_data(address, register), length)
        else:
            raise ValueError("Unsupported register length")
    except Exception as e:
        raise RuntimeError(f"Failed to read from register {register}: {e}")



class I2CDevice:
    """A generic I2C device class for interacting with I2C sensors and actuators."""

    def __init__(self, address, bus_number=1, length=8, debug=False):
        """Initializes the I2C device."""
        self.address = address
        self.bus_number = bus_number
        self.length = length
        self.debug = debug
        self._device = None  # Use context manager for resource management

    def __enter__(self):
        """Context manager entry point, opens the I2C device."""
        self._device = _create_i2c_device(self.address, self.bus_number, self.length, self.debug)
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        """Context manager exit point, closes the I2C device."""
        if self._device:
            return True  # Indicate successful cleanup


    def write_register(self, register, value):
        """Writes a value to a register on the I2C device."""
        if not self._device:
            raise RuntimeError("Device not initialized, use __enter__.")
        return _write_register_value(self._device, self.address, register, value, self.length)

    def read_register(self, register):
        """Reads a value from a register on the I2C device."""
        if not self._device:
            raise RuntimeError("Device not initialized, use __enter__.")
        return _read_register_value(self._device, self.address, register, self.length)

