import time
import board
import busio
import adafruit_ccs811

# Define the I2C bus for the Raspberry Pi
I2C_BUS = 1

# CCS811 sensor I2C address
CCS811_ADDRESS = 0x5A

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except ValueError as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_sensor(i2c_bus):
    """Initialize the CCS811 sensor."""
    try:
        return adafruit_ccs811.CCS811(i2c_bus, address=CCS811_ADDRESS)
    except ValueError as e:
        print(f"Error initializing CCS811 sensor: {e}")
        return None

def read_co2_level(sensor):
    """Read the CO2 concentration from the sensor."""
    if sensor.data_ready:
        return sensor.eco2
    return None

def main():
    """Main function to read and print CO2 levels."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    sensor = initialize_sensor(i2c_bus)
    if sensor is None:
        return

    try:
        for _ in range(5):
            co2_level = read_co2_level(sensor)
            if co2_level is not None:
                print(f"CO2 Concentration: {co2_level} ppm")
            time.sleep(2)
    except (OSError, IOError) as e:
        print(f"I2C Communication Error: {e}")
    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        # No specific cleanup needed for I2C or CCS811 in this library
        print("Exiting program.")

if __name__ == "__main__":
    main()

