DS1338_ADDRESS = 0x68
DS1338_CONTROL_REGISTER = 0x00
DS1338_SECONDS_REGISTER = 0x00
DS1338_MINUTES_REGISTER = 0x01
DS1338_HOURS_REGISTER = 0x02
DS1338_DAY_REGISTER = 0x03
DS1338_DATE_REGISTER = 0x04
DS1338_MONTH_REGISTER = 0x05
DS1338_YEAR_REGISTER = 0x06


class DS1338Error(Exception):
    """Custom exception for DS1338 communication errors."""
    pass


def bcd_to_int(bcd_value):
    """Converts a BCD value to an integer."""
    try:
        return (bcd_value >> 4) * 10 + (bcd_value & 0x0F)
    except TypeError:
        raise DS1338Error("Invalid BCD value provided")


def int_to_bcd(int_value):
    """Converts an integer to BCD format."""
    if not 0 <= int_value <= 99:
        raise DS1338Error("Integer value must be between 0 and 99 for BCD conversion.")
    return (int_value // 10 << 4) | (int_value % 10)


class DS1338:
    """Driver class for the DS1338 Real-Time Clock (RTC) module."""

    def __init__(self, i2c_bus_number=1):
        """Initializes the DS1338 driver.

        Args:
            i2c_bus_number (int): The I2C bus number the DS1338 is connected to.
        """
        try:
             with contextlib.closing(smbus.SMBus(i2c_bus_number)) as self.bus:  # Use context manager for resource management
                self.bus = self.bus
        except Exception as e:
            raise DS1338Error(f"Failed to initialize I2C bus: {e}")

        self.i2c_bus_number = i2c_bus_number
        self._initialize()

    def _initialize(self):
        """Initializes the DS1338 by checking its presence and setting the clock mode."""
        try:
            self.bus.write_byte(DS1338_ADDRESS, DS1338_CONTROL_REGISTER, 0x00) # Reset
            self.bus.write_byte(DS1338_ADDRESS, DS1338_CONTROL_REGISTER, 0x03) # Initialize
            time_now = datetime.now(timezone.utc)
            self.write_datetime(time_now)  # Set to a known time for testing
        except Exception as e:
            raise DS1338Error(f"Failed to initialize DS1338: {e}")


    def _write_register(self, register_address, data):
        """Writes a byte of data to a specific register on the DS1338."""
        try:
            self.bus.write_byte(DS1338_ADDRESS, register_address, data)
        except Exception as e:
            raise DS1338Error(f"Failed to write to register {register_address}: {e}")


    def _read_register(self, register_address):
        """Reads a byte of data from a specific register on the DS1338."""
        try:
            return self.bus.read_byte_data(DS1338_ADDRESS, register_address)
        except Exception as e:
            raise DS1338Error(f"Failed to read from register {register_address}: {e}")

    def write_datetime(self, dt):
        """Writes the given datetime object to the DS1338."""
        try:
            year = dt.year - 2000
            self._write_register(DS1338_YEAR_REGISTER, int_to_bcd(year))

            month = dt.month
            self._write_register(DS1338_MONTH_REGISTER, int_to_bcd(month))

            day = dt.day
            self._write_register(DS1338_DATE_REGISTER, int_to_bcd(day))

            hours = dt.hour
            self._write_register(DS1338_HOURS_REGISTER, int_to_bcd(hours))  # Assuming dt.hour is in 24-hour format

            minutes = dt.minute
            self._write_register(DS1338_MINUTES_REGISTER, int_to_bcd(minutes))

            seconds = dt.second
            self._write_register(DS1338_SECONDS_REGISTER, int_to_bcd(seconds))

            # Set clock mode to running (CH = 0)
            self._write_register(DS1338_CONTROL_REGISTER, 0x00)

        except Exception as e:
            raise DS1338Error(f"Failed to write datetime to DS1338: {e}")

    def read_datetime(self):
        """Reads the current datetime from the DS1338 and returns a datetime object."""
        try:
            years_century = self._read_register(DS1338_YEAR_REGISTER)
            months = bcd_to_int(self._read_register(DS1338_MONTH_REGISTER))
            days = bcd_to_int(self._read_register(DS1338_DATE_REGISTER))
            hours = bcd_to_int(self._read_register(DS1338_HOURS_REGISTER)) # Still assuming 24-hour format
            minutes = bcd_to_int(self._read_register(DS1338_MINUTES_REGISTER))
            seconds = bcd_to_int(self._read_register(DS1338_SECONDS_REGISTER))

            year = 2000 + years_century
            dt = datetime(year, months, days, hours, minutes, seconds, timezone.utc)
            return dt

        except Exception as e:
            raise DS1338Error(f"Failed to read datetime from DS1338: {e}")


    def close(self):
        """Closes the I2C bus connection."""
        try:
            self.bus.close()
        except Exception as e:
            print(f"Error closing bus: {e}")  # Print error but don't raise



if __name__ == "__main__":
    try:
        rtc = DS1338()
        now = rtc.read_datetime()
        print(f"Current time: {now}")
    except DS1338Error as e:
        print(f"Error: {e}")
        exit(1) # Indicate an error

