#!/usr/bin/env python3

import RPi.GPIO as GPIO
import time
import logging
import argparse
import json
import smbus
from datetime import datetime

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Default configuration values
DEFAULT_CONFIG = {
    "zone1_on": 1234,
    "zone1_off": 5678,
    "zone2_on": 9012,
    "zone2_off": 3456,
    "gpio_pin": 17,
    "transmission_repeat": 3
}

def load_config(config_file):
    """Loads configuration from a JSON file."""
    try:
        with open(config_file, 'r') as f:
            config = json.load(f)
        # Validate config data types
        if not all(isinstance(config.get(f"zone{i}_on", None), int) for i in range(1, 3)):
            raise ValueError("zone1_on, zone1_off, zone2_on, zone2_off must be integers.")
        if not all(isinstance(config.get(f"gpio_pin", None), int) for _ in range(1)):
            raise ValueError("gpio_pin must be an integer.")
        if not all(isinstance(config.get(f"transmission_repeat", None), int) for _ in range(1)):
            raise ValueError("transmission_repeat must be an integer.")
        return config
    except FileNotFoundError:
        logging.error(f"Configuration file not found: {config_file}")
        return None
    except json.JSONDecodeError:
        logging.error(f"Invalid JSON in configuration file: {config_file}")
        return None
    except ValueError as e:
        logging.error(f"Invalid configuration data: {e}")
        return None

def setup_gpio(gpio_pin):
    """Sets up the GPIO pin for RF transmission."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(gpio_pin, GPIO.OUT)
        GPIO.output(gpio_pin, GPIO.LOW)  # Ensure the pin is initially low
        logging.info(f"GPIO pin {gpio_pin} set up for RF transmission.")
    except Exception as e:
        logging.error(f"Error setting up GPIO pin {gpio_pin}: {e}")
        raise

def transmit_rf_code(gpio_pin, rf_code, repeat_count):
    """Transmits the RF code using OOK modulation."""
    try:
        logging.info(f"Transmitting RF code: {rf_code} on GPIO {gpio_pin}, repeat {repeat_count}")
        for _ in range(repeat_count):
            for bit in str(rf_code).encode('utf-8'):
                GPIO.output(gpio_pin, bit == 49)  # 49 is the ASCII value for '1'
                time.sleep(0.001)  # 1ms pulse
            time.sleep(0.01)  # Gap between repeats
    except Exception as e:
        logging.error(f"Error transmitting RF code: {e}")
        raise

def get_current_time():
    """Gets the current time from the RTC module or system clock."""
    try:
        # Attempt to read from the RTC module
        bus = smbus.SMBus(1)  # Use I2C bus 1
        rtc_address = 0x68  # Default address for DS3231
        data = bus.read_i2c_block_data(rtc_address, 0x00, 7)
        seconds = bcd_to_decimal(data[0] & 0x7F)
        minutes = bcd_to_decimal(data[1])
        hours = bcd_to_decimal(data[2] & 0x3F)
        logging.info("Time retrieved from RTC module.")
        return seconds, minutes, hours
    except Exception as e:
        logging.warning(f"Failed to read from RTC module: {e}. Using system clock.")
        return None

def bcd_to_decimal(bcd):
    """Converts a BCD value to decimal."""
    return (bcd >> 4) * 10 + (bcd & 0x0F)

def control_zone(zone_number, action, config, gpio_pin):
    """Controls the specified irrigation zone."""
    try:
        if zone_number == 1:
            rf_code = config["zone1_on"] if action == "on" else config["zone1_off"]
        elif zone_number == 2:
            rf_code = config["zone2_on"] if action == "on" else config["zone2_off"]
        else:
            raise ValueError("Invalid zone number. Must be 1 or 2.")

        transmit_rf_code(gpio_pin, rf_code, config["transmission_repeat"])
        logging.info(f"Zone {zone_number} turned {action}.")

    except KeyError as e:
        logging.error(f"Missing configuration value: {e}")
        raise
    except ValueError as e:
        logging.error(f"Invalid zone number: {e}")
        raise
    except Exception as e:
        logging.error(f"Error controlling zone {zone_number}: {e}")
        raise

def main():
    """Main function to parse arguments and control the irrigation system."""
    parser = argparse.ArgumentParser(description="Control irrigation zones using 433MHz RF transmitters.")
    parser.add_argument("zone", choices=['zone1', 'zone2'], help="The irrigation zone to control (zone1 or zone2).")
    parser.add_argument("action", choices=['on', 'off'], help="The action to perform (on or off).")
    args = parser.parse_args()

    config_file = "irrigation_config.json"
    config = load_config(config_file)

    if not config:
        print("Failed to load configuration. Exiting.")
        exit(1)

    gpio_pin = config["gpio_pin"]
    try:
        setup_gpio(gpio_pin)
    except Exception:
        print("Failed to set up GPIO. Exiting.")
        exit(1)

    try:
        seconds, minutes, hours = get_current_time()
        if seconds is None:
            seconds, minutes, hours = datetime.now().timetuple()[:3]
        logging.info(f"Current time: {hours:02d}:{minutes:02d}:{seconds:02d}")

        control_zone(args.zone, args.action, config, gpio_pin)

    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        GPIO.cleanup()  # Clean up GPIO on exit
        logging.info("GPIO cleaned up. Program exiting.")

if __name__ == "__main__":
    main()

