# Configure logging
logging.basicConfig(
    level=logging.INFO, format="%(asctime)s - %(levelname)s - %(message)s"
)

# Constants
DEFAULT_PORT = "/dev/serial0"
DEFAULT_BAUDRATE = 115200
TIMEOUT = 1.0
TERMINATOR = b"OK"  # Use bytes for terminator

# Global UART port (initialized later)
uart_port = None

Event = threading.Event


def _safe_read(uart: serial.Serial, timeout: float) -> Optional[bytes]:
    """Reads data from the UART port with error handling."""
    try:
        return uart.read(timeout=timeout)
    except serial.SerialException as e:
        logging.error(f"UART read error: {e}")
        return None


def _safe_write(uart: serial.Serial, data: bytes) -> bool:
    """Writes data to the UART port with error handling."""
    try:
        uart.write(data)
        return True
    except serial.SerialException as e:
        logging.error(f"UART write error: {e}")
        return False


def _send_command(command: bytes, timeout: float = TIMEOUT) -> Optional[bytes]:
    """Sends an AT command to the ESP8266 and reads the response."""
    if not uart_port or not _safe_write(uart_port, command):
        return None

    if _safe_read(uart_port, timeout) is None:
        return None

    response = b""
    start_time = time.time()
    while time.time() - start_time < timeout and response != TERMINATOR:
        chunk = _safe_read(uart_port, TIMEOUT)
        if chunk is None:
            return None
        response += chunk

    return response if response else None


def _check_response(response: bytes, expected: bytes, timeout: float = TIMEOUT) -> bool:
    """Checks if the response contains the expected substring within a timeout."""
    if not uart_port or not _safe_read(uart_port, timeout):
        return False

    start_time = time.time()
    while time.time() - start_time < timeout:
        response = _safe_read(uart_port, TIMEOUT)
        if response is None:
            return False
        if expected in response:
            return True
    return False


def _wait_for_event(event: Event, timeout: float = TIMEOUT) -> bool:
    """Waits for an event to be set within a timeout."""
    return event.wait(timeout) if event else False


def _handle_exception(func: Callable) -> Callable:
    """Decorator for handling exceptions in command functions."""

    def wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except Exception as e:
            logging.error(f"Exception in {func.__name__}: {e}")
            return None

    return wrapper


class ESP8266:
    """A class for interacting with an ESP8266 Wi-Fi module."""

    def __init__(self, port: str = DEFAULT_PORT, baudrate: int = DEFAULT_BAUDRATE):
        """Initializes the ESP8266 object."""
        self.port = port
        self.baudrate = baudrate
        global uart_port  # Access the global UART port
        try:
            uart_port = serial.Serial(port=self.port, baudrate=self.baudrate, timeout=TIMEOUT)
            logging.info(f"UART port {self.port} initialized successfully.")
        except serial.SerialException as e:
            logging.error(f"Failed to initialize UART port {self.port}: {e}")
            uart_port = None

    def _send(self, command: bytes) -> Optional[bytes]:
        """Sends an AT command to the ESP8266."""
        return _send_command(command)

    def test_connection(self) -> bool:
        """Tests the connection to the ESP8266."""
        if not uart_port:
            logging.error("UART port not initialized.")
            return False

        response = self._send(b"AT\r\n")
        return response is not None and TERMINATOR in response

    @_handle_exception
    def restart(self) -> None:
        """Restarts the ESP8266 module."""
        if not uart_port:
            logging.error("UART port not initialized.")
            return

        if not self._send(b"AT+RST\r\n"):
            return

        # Wait for the module to restart
        event = Event()
        threading.Timer(2.0, event.set).start()  # Adjust timeout as needed
        if _wait_for_event(event):
            logging.info("ESP8266 restarted successfully.")
        else:
            logging.error("ESP8266 restart failed.")

    @_handle_exception
    def connect_wifi(self, ssid: str, password: str) -> Optional[bytes]:
        """Connects to a Wi-Fi network."""
        if not uart_port:
            logging.error("UART port not initialized.")
            return None

        command = f'AT+CWJAP="{ssid}","{password}"\r\n'.encode("utf-8")
        response = self._send(command)
        if not response:
            return None

        # Wait for connection establishment
        event = Event()
        threading.Timer(10.0, event.set).start()  # Adjust timeout as needed
        if _wait_for_event(event):
            ip_address = self.get_ip()
            if ip_address:
                logging.info(f"Connected to Wi-Fi. IP address: {ip_address}")
                return response
            else:
                logging.warning("Failed to get IP address after connection.")
        else:
            logging.error("Wi-Fi connection failed.")
        return response

    @_handle_exception
    def disconnect_wifi(self) -> None:
        """Disconnects from the Wi-Fi network."""
        if not uart_port:
            logging.error("UART port not initialized.")
            return

        if not self._send(b"AT+CWQAP\r\n"):
            return

        # Wait for disconnection
        event = Event()
        threading.Timer(5.0, event.set).start()  # Adjust timeout as needed
        _wait_for_event(event)
        logging.info("Wi-Fi disconnected.")

    @_handle_exception
    def get_ip(self) -> Optional[str]:
        """Retrieves the IP address of the ESP8266."""
        if not uart_port:
            logging.error("UART port not initialized.")
            return None

        response = self._send(b"AT+CIFSR\r\n")
        if not response:
            return None

        try:
            # Find the IP address in the response
            ip_address = response.decode("utf-8").splitlines()[1].split('"')[1]
            logging.info(f"IP address: {ip_address}")
            return ip_address
        except (IndexError, ValueError):
            logging.error("Failed to parse IP address.")
            return None

    @_handle_exception
    def send_http_request(
        self,
        method: str,
        url: str,
        host: str,
        port: int = 80,
        headers: Optional[dict] = None,
        data: Optional[str] = None,
    ) -> Optional[bytes]:
        """Sends an HTTP request to a server."""

        if not uart_port:
            logging.error("UART port not initialized.")
            return None

        # Construct the request
        request = (
            f"AT+CIPSTART=\"TCP\",\"{host}\",{port}\r\n"
            + f"AT+CIPSEND={url.length if 'length' in url else len(url)}\r\n"
            + f"{method.upper()} {url} HTTP/1.1\r\n"
        )
        if headers:
            for key, value in headers.items():
                request += f"{key}: {value}\r\n"
        request += "\r\n"
        if data:
            request += data
        request += "\r\n"

        # Send the request
        response = self._send(request.encode("utf-8"))
        if not response:
            return None

        # Read the response
        response_data = b""
        while True:
            status, response_data = self._read_response()
            if status == 1:
                break
            elif status == 0:
                logging.warning("Connection closed unexpectedly.")
                break
            else:
                logging.warning(f"Unexpected status: {status}")

        return response_data

    def _read_response(self) -> Tuple[int, bytes]:
        """Reads the HTTP response from the server."""
        response_data = b""
        status = 0
        chunk = self._safe_read(uart_port, TIMEOUT)
        if chunk:
            response_data += chunk
            status = 1 if b"HTTP/1.1 200 OK" in chunk else 0
        return status, response_data

    def cleanup(self) -> None:
        """Closes the UART port."""
        if uart_port:
            uart_port.close()
            logging.info("UART port closed.")


def _signal_handler(signum: int, frame) -> None:
    """Handles signals for graceful shutdown."""
    logging.info("Signal received, closing UART port...")
    if uart_port:
        uart_port.close()
    logging.info("UART port closed. Exiting.")


def main() -> None:
    """Main function to demonstrate ESP8266 functionality."""
    esp = ESP8266(port="/dev/serial0", baudrate=115200)

    if not esp.test_connection():
        logging.error("Failed to connect to ESP8266.")
        return

    # Example usage:
    esp.restart()
    time.sleep(2)
    ip_address = esp.get_ip()
    if ip_address:
        print(f"IP address: {ip_address}")

        response = esp.send_http_request(
            "GET", "http://www.example.com", "www.example.com", port=80
        )
        if response:
            print(f"Response length: {len(response)}")

        esp.disconnect_wifi()
    else:
        logging.error("Failed to get IP address.")


if __name__ == "__main__":
    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    main()

