import serial
import time
import RPi.GPIO as GPIO

# Constants
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
ALARM_GPIO_PIN = 18
RADIATION_THRESHOLD = 50.0
SLEEP_INTERVAL = 1


def configure_serial(port, baudrate, timeout):
    """Configures and returns a serial port object."""
    try:
        return serial.Serial(port, baudrate, timeout=timeout)
    except serial.SerialException as e:
        print(f"Error configuring serial port: {e}")
        return None


def configure_gpio(pin):
    """Configures the GPIO pin as an output."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(pin, GPIO.OUT)


def read_radiation_level(serial_port):
    """Reads radiation level from the serial port."""
    try:
        line = serial_port.readline().decode('ascii', errors='replace').strip()
        if line:
            return float(line)
        return None
    except ValueError:
        print("Error: Could not convert line to float.")
        return None
    except Exception as e:
        print(f"Error reading from serial port: {e}")
        return None


def set_alarm_state(pin, level, threshold):
    """Sets the alarm state based on the radiation level."""
    if level > threshold:
        GPIO.output(pin, GPIO.HIGH)  # Activate alarm
        print("Radiation level HIGH! Alarm activated.")
    else:
        GPIO.output(pin, GPIO.LOW)  # Deactivate alarm
        print("Radiation level normal. Alarm deactivated.")


def main():
    """Main function to read radiation data and control the alarm."""
    serial_connection = configure_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_connection is None:
        exit(1)

    configure_gpio(ALARM_GPIO_PIN)

    try:
        while True:
            level = read_radiation_level(serial_connection)
            if level is not None:
                set_alarm_state(ALARM_GPIO_PIN, level, RADIATION_THRESHOLD)
            time.sleep(SLEEP_INTERVAL)
    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        serial_connection.close()
        GPIO.cleanup()
        print("Resources cleaned up. Exiting.")


if __name__ == "__main__":
    main()

