import serial
import time
import RPi.GPIO as GPIO

# Constants
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
ALARM_GPIO_PIN = 18
RADIATION_THRESHOLD = 50.0
READ_TIMEOUT = 1
SLEEP_INTERVAL = 1


def initialize_serial(port, baud, timeout):
    """Initializes and returns a serial port object."""
    try:
        return serial.Serial(port, baud, timeout=timeout)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None


def initialize_gpio(pin):
    """Initializes the GPIO pin for the alarm."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(pin, GPIO.OUT)
    GPIO.output(pin, GPIO.LOW)  # Initialize to LOW


def read_radiation_level(serial_port):
    """Reads radiation level from the serial port."""
    try:
        data = serial_port.readline().decode('ascii', errors='replace').strip()
        if data:
            return float(data)
        return None
    except ValueError:
        print("Invalid data received from serial port.")
        return None
    except serial.SerialException as e:
        print(f"Serial port error: {e}")
        return None


def set_alarm_state(pin, level, threshold):
    """Sets the alarm state based on the radiation level."""
    try:
        if level > threshold:
            GPIO.output(pin, GPIO.HIGH)
            print("Alarm: Radiation level exceeded threshold!")
        else:
            GPIO.output(pin, GPIO.LOW)
        return GPIO.input(pin)  # Return current state
    except RPi.GPIO.exceptions.RuntimeError as e:
        print(f"GPIO error: {e}")
        return None


def main():
    """Main function to read radiation data and control the alarm."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, READ_TIMEOUT)
    if serial_connection is None:
        exit(1)

    initialize_gpio(ALARM_GPIO_PIN)

    alarm_active = False

    try:
        while True:
            level = read_radiation_level(serial_connection)
            if level is not None:
                print(f"Radiation Level: {level:.2f} µSv/h")
                new_alarm_state = set_alarm_state(ALARM_GPIO_PIN, level, RADIATION_THRESHOLD)
                if new_alarm_state is not None and new_alarm_state != alarm_active:
                    alarm_active = new_alarm_state
                    print(f"Alarm state changed to: {alarm_active}")
            time.sleep(SLEEP_INTERVAL)
    except KeyboardInterrupt:
        print("Exiting program...")
    finally:
        serial_connection.close()
        GPIO.cleanup()
        print("Resources cleaned up.")


if __name__ == "__main__":
    main()

