# uart_power_meter_smart_energy.py
# Reads power consumption data from a UART-connected smart energy meter and logs it.
# Target: Raspberry Pi 3 Model B+

import serial
import time
import datetime
import os

# Configuration
SERIAL_PORT = '/dev/serial0'  # UART port on Raspberry Pi
BAUD_RATE = 9600
TIMEOUT = 1  # seconds
LOG_FILE = 'power_consumption.log'

def initialize_serial(port, baudrate, timeout):
    """Initializes the serial connection."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def read_power_data(serial_port):
    """Reads a line of data from the serial port."""
    try:
        data = serial_port.readline().decode('ascii', errors='replace').strip()
        return data
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
        return None

def parse_power_value(data):
    """Parses the power value from the data string."""
    if data:
        try:
            power = float(data)
            return power
        except ValueError:
            print(f"Invalid data received: {data}")
            return None
    return None

def log_power_consumption(power, log_file):
    """Logs the power consumption data to a file."""
    timestamp = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f'{timestamp} – Power: {power} W'
    try:
        with open(log_file, 'a') as file:
            file.write(log_entry + '\n')
        print(log_entry)
    except IOError as e:
        print(f"Error writing to log file: {e}")

def main():
    """Main function to read, parse, and log power consumption data."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)

    if serial_connection is None:
        print("Failed to initialize serial connection. Exiting.")
        return

    try:
        while True:
            data = read_power_data(serial_connection)
            power_value = parse_power_value(data)
            if power_value is not None:
                log_power_consumption(power_value, LOG_FILE)
            time.sleep(1)  # 1 second timeout
    except KeyboardInterrupt:
        print("Program terminated by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

